function updateBookmarksDropdown() {
    const listEl = document.getElementById('bookmark-items-list');
    if (!listEl) return;
    listEl.innerHTML = '';

    if (!activeProject) return;

    const displayList = [];
    projects.forEach(p => {
        const isCurrent = (p.name === activeProject);
        const bookmarks = p.bookmarks || [];
        bookmarks.forEach((bm, idx) => {
            // Extract dictionary command/global properties
            const cmdText = (typeof bm === 'string') ? bm : (bm.command || '');
            const isGlobal = (typeof bm === 'object') ? (bm.global === true) : false;
            const bmName = (typeof bm === 'object') ? (bm.name || '') : '';
            const windowTitle = (typeof bm === 'object') ? (bm.windowTitle || '') : '';
            const bmColor = (typeof bm === 'object' && /^#[0-9a-fA-F]{6}$/.test(bm.color || '')) ? bm.color : '';

            if (isCurrent || isGlobal) {
                displayList.push({
                    command: cmdText,
                    global: isGlobal,
                    name: bmName,
                    windowTitle: windowTitle,
                    color: bmColor,
                    displayOrder: (typeof bm === 'object' && Number.isFinite(Number(bm.displayOrder))) ? Number(bm.displayOrder) : null,
                    project: p.name,
                    index: idx,
                    isOwned: isCurrent
                });
            }
        });
    });

    // De-duplicate command display list
    const seen = new Set();
    const uniqueList = [];
    displayList.forEach(item => {
        const key = item.command.toLowerCase();
        if (!seen.has(key)) {
            seen.add(key);
            uniqueList.push(item);
        }
    });

    // Use the persisted merged-list order when available. Items without
    // an order retain their existing workspace/configuration order.
    uniqueList.sort((a, b) => {
        const aHasOrder = Number.isFinite(a.displayOrder);
        const bHasOrder = Number.isFinite(b.displayOrder);
        if (aHasOrder && bHasOrder) return a.displayOrder - b.displayOrder;
        if (aHasOrder) return -1;
        if (bHasOrder) return 1;
        return 0;
    });

    if (uniqueList.length === 0) {
        listEl.innerHTML = '<div style="color: var(--text-secondary); font-size: 0.85rem; text-align: center; padding: 12px 10px;">No bookmarked commands.</div>';
    } else {
        uniqueList.forEach((bm, idx) => {
            const row = document.createElement('div');
            row.className = 'bookmark-item';

            const isLast = (idx === uniqueList.length - 1);
            const borderStyle = isLast ? 'none' : '1px solid var(--border-color)';

            row.style = `display: flex; align-items: center; justify-content: space-between; padding: 8px 12px; cursor: pointer; transition: background-color 0.15s; border-bottom: ${borderStyle};`;

            // Match container's border radius for rounded edges on hover
            if (idx === 0) {
                row.style.borderTopLeftRadius = '7px';
                row.style.borderTopRightRadius = '7px';
            }
            if (isLast) {
                row.style.borderBottomLeftRadius = '7px';
                row.style.borderBottomRightRadius = '7px';
            }
            row.onmouseenter = () => {
                row.style.backgroundColor = 'var(--bg-card-hover)';
            };
            row.onmouseleave = () => {
                row.style.backgroundColor = 'transparent';
            };
            row.onclick = () => runBookmarkedCommand(bm.command, bm.windowTitle);
            row.oncontextmenu = (e) => {
                e.preventDefault();
                e.stopPropagation();
                openBookmarkModal(bm.project, bm.index, bm.command, bm.name, bm.windowTitle, bm.color);
            };

            // Drag-to-reorder is available for local and global bookmarks.
            // A bookmark is still reordered only within its source workspace.
            {
                row.draggable = true;
                row.dataset.bmIdx = idx;
                row.dataset.bmProject = bm.project;
                row.dataset.bmOrigIndex = bm.index;

                row.addEventListener('dragstart', (e) => {
                    e.dataTransfer.effectAllowed = 'move';
                    e.dataTransfer.setData('text/plain', idx);
                    row.style.opacity = '0.45';
                    _bmDragSrcIdx = idx;
                });
                row.addEventListener('dragend', () => {
                    row.style.opacity = '1';
                    // Remove all drop indicators
                    document.querySelectorAll('.bookmark-item').forEach(r => r.style.borderTop = '');
                });
                row.addEventListener('dragover', (e) => {
                    e.preventDefault();
                    e.dataTransfer.dropEffect = 'move';
                    // Visual indicator
                    document.querySelectorAll('.bookmark-item').forEach(r => r.style.borderTop = '');
                    if (_bmDragSrcIdx !== idx) row.style.borderTop = '2px solid var(--accent-color)';
                });
                row.addEventListener('dragleave', () => {
                    row.style.borderTop = '';
                });
                row.addEventListener('drop', (e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    row.style.borderTop = '';
                    const fromIdx = _bmDragSrcIdx;
                    const toIdx = idx;
                    if (fromIdx === toIdx || fromIdx === null) return;
                    reorderBookmark(uniqueList, fromIdx, toIdx);
                });
            }

            const displayName = bm.name ? bm.name : bm.command;
            row.title = `Right click to edit\nCommand: ${bm.command}${bm.windowTitle ? `\nWindow Title: ${bm.windowTitle}` : ''}`;

            const dragHandle = `<span class="bm-drag-handle" title="Drag to reorder within ${bm.project}" style="color:var(--text-muted); cursor:grab; font-size:0.9rem; padding:0 4px 0 0; flex-shrink:0; user-select:none; opacity:0.5;" onmouseenter="this.style.opacity='1'" onmouseleave="this.style.opacity='0.5'">⠿</span>`;

            const bmCmdEsc = bm.command.replace(/\\/g, '\\\\').replace(/'/g, "\\'");

            // Build inline subcmd buttons HTML
            const subcmds = loadSubcmds(bm.command);
            let subcmdButtonsHtml = '';
            subcmds.forEach((sc, i) => {
                const label = sc.label || sc.cmd;
                const labelEsc = label.replace(/"/g, '&quot;').replace(/</g, '&lt;');
                const scCmdEsc = sc.cmd.replace(/\\/g, '\\\\').replace(/'/g, "\\'");
                let btnStyle = `display:inline-flex;align-items:center;padding:2px 8px;border-radius:5px;font-size:0.72rem;cursor:pointer;border:1px solid;white-space:nowrap;transition:filter 0.15s;`;
                btnStyle += `background:${sc.bg || 'var(--bg-sidebar)'};`;
                btnStyle += `color:${sc.fg || 'var(--text-primary)'};`;
                btnStyle += `border-color:${sc.borderColor || 'var(--border-color)'};`;
                if (sc.borderWidth != null) btnStyle += `border-width:${sc.borderWidth}px;`;
                if (sc.borderRadius != null) btnStyle += `border-radius:${sc.borderRadius}px;`;
                subcmdButtonsHtml += `<div class="bm-subcmd-wrap" style="position:relative;display:inline-flex;">
                    <button type="button" class="bm-subcmd-btn" title="${scCmdEsc}" style="${btnStyle}" onclick="event.stopPropagation();runSubcmd('${scCmdEsc}')" onmouseenter="this.style.filter='brightness(1.3)'" onmouseleave="this.style.filter=''">${labelEsc}</button>
                    <span class="bm-subcmd-edit-overlay" title="Edit" onclick="event.stopPropagation();openSubcmdEditModal('${bmCmdEsc}',${i})">✎</span>
                </div>`;
            });
            subcmdButtonsHtml += `<button type="button" class="bm-subcmd-add-btn" onclick="event.stopPropagation();openSubcmdEditModal('${bmCmdEsc}',null)" title="Add sub-command">+</button>`;

            row.innerHTML = `
                ${dragHandle}
                <span style="font-size: 0.85rem; color: ${bm.color || 'var(--text-primary)'}; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; flex-shrink: 0; max-width: 120px;" title="${bm.command}">${displayName}</span>
                <div class="bm-subcmds-inline" style="display:flex;flex-wrap:wrap;align-items:center;gap:4px;flex:1;overflow:hidden;padding:0 6px;" onclick="event.stopPropagation()">
                    ${subcmdButtonsHtml}
                </div>
                <div style="display: flex; align-items: center; gap: 8px; flex-shrink: 0;">
                    <button type="button" style="background: none; border: none; color: var(--accent-color); cursor: pointer; padding: 4px; border-radius: 4px; display: flex; align-items: center; justify-content: center; font-size: 0.8rem; transition: background-color 0.2s;" onmouseenter="this.style.backgroundColor='rgba(255,255,255,0.08)'" onmouseleave="this.style.backgroundColor='transparent'" onclick="event.stopPropagation(); runBookmarkInSplit('${bmCmdEsc}')" title="Run in new split terminal">
                        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" style="color: var(--accent-color);">
                            <rect x="3" y="3" width="18" height="18" rx="2" ry="2"></rect>
                            <line x1="12" y1="3" x2="12" y2="21"></line>
                        </svg>
                    </button>
                    <label class="switch-toggle" onclick="event.stopPropagation();" style="position: relative; display: inline-block; width: 28px; height: 16px; margin: 0; cursor: pointer; flex-shrink: 0;" title="${bm.global ? 'Make local (visible only in this workspace)' : 'Make global (visible in all workspaces)'}">
                        <input type="checkbox" ${bm.global ? 'checked' : ''} onchange="toggleBookmarkGlobal('${bm.project}', ${bm.index}, this.checked)" style="opacity: 0; width: 0; height: 0; position: absolute;">
                        <span class="slider-round" style="position: absolute; cursor: pointer; top: 0; left: 0; right: 0; bottom: 0; background-color: ${bm.global ? 'var(--accent-color)' : '#475569'}; transition: 0.2s; border-radius: 16px;">
                            <span style="position: absolute; content: ''; height: 12px; width: 12px; left: ${bm.global ? '14px' : '2px'}; bottom: 2px; background-color: white; transition: 0.2s; border-radius: 50%;"></span>
                        </span>
                    </label>
                    <button type="button" style="background: none; border: none; color: #f87171; cursor: pointer; padding: 4px; border-radius: 4px; display: flex; align-items: center; justify-content: center; font-size: 0.8rem; transition: background-color 0.2s;" onmouseenter="this.style.backgroundColor='rgba(255,255,255,0.08)'" onmouseleave="this.style.backgroundColor='transparent'" onclick="event.stopPropagation(); deleteBookmark('${bm.project}', ${bm.index})">❌</button>
                </div>
            `;

            listEl.appendChild(row);
        });
    }
}

